254→// enrichSessionState loads the session state after initialization and populates it with
255→// transcript-derived metadata (token usage, turn count, model name, duration).
256→func enrichSessionState(ctx context.Context, sessionID string, ag agent.Agent, transcriptData []byte, transcriptPath string) error {
257→	state, err := strategy.LoadSessionState(ctx, sessionID)
258→	if err != nil {
259→		return fmt.Errorf("failed to load session state: %w", err)
260→	}
261→	if state == nil {
262→		return fmt.Errorf("session state not found after initialization (session_id=%s)", sessionID)
263→	}
264→	state.CLIVersion = versioninfo.Version
265→	state.TranscriptPath = transcriptPath
266→
267→	if usage := agent.CalculateTokenUsage(ctx, ag, transcriptData, 0, ""); usage != nil {
268→		state.TokenUsage = usage
269→	}
270→	if turns := countUserTurns(transcriptData); turns > 0 {
271→		state.SessionTurnCount = turns
272→	}
273→	if model := extractModelFromTranscript(transcriptData); model != "" {
274→		state.ModelName = model
275→	}
276→	if dur := estimateSessionDuration(transcriptData); dur > 0 {
277→		state.SessionDurationMs = dur
278→	}
279→
280→	if err := strategy.SaveSessionState(ctx, state); err != nil {
281→		return fmt.Errorf("failed to save session state: %w", err)
282→	}
283→	return nil
284→}
285→
286→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
287→// Returns the checkpoint ID string and any condensation error.
288→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
289→	var checkpointIDStr string
290→	var condenseErr error
291→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
292→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
293→		condenseErr = err
294→	}
295→
296→	// Single load serves both checkpoint ID extraction and finalization
297→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
298→	if loadErr != nil {
299→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
300→		return checkpointIDStr, condenseErr
301→	}
302→	if state == nil {
303→		return checkpointIDStr, condenseErr
304→	}
305→
306→	if condenseErr == nil {
307→		checkpointIDStr = state.LastCheckpointID.String()
308→	}
309→
310→	now := time.Now()
311→	state.LastInteractionTime = &now
312→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
313→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
314→	}
315→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
316→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
317→	}
318→
319→	return checkpointIDStr, condenseErr
320→}
321→
322→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
323→// project directories if needed.
324→func resolveAndValidateTranscript(ctx context.Context, sessionID string, agentName types.AgentName, ag agent.Agent) (string, error) {
325→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
326→	if err != nil {
327→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
328→	}
329→	// If agent implements TranscriptPreparer, materialize the transcript before checking disk.
330→	if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
331→		if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
332→			logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
333→		}
334→	}
335→	// Agents use cwd-derived project directories, so the transcript may be stored under
336→	// a different project directory if the session was started from a different working directory.
337→	if _, statErr := os.Stat(transcriptPath); statErr == nil {
338→		return transcriptPath, nil
339→	}
340→	found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag)
341→	if searchErr == nil {
342→		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
343→		return found, nil
344→	}
345→	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
346→	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
347→}
348→
349→// detectAgentByTranscript tries all registered agents (except skip) to find one whose
350→// transcript resolution succeeds for the given session ID.
351→func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
352→	for _, name := range agent.List() {
353→		if name == skip {
354→			continue
355→		}
356→		ag, err := agent.Get(name)
357→		if err != nil {
358→			continue
359→		}
360→		if path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, name, ag); resolveErr == nil {
361→			return ag, path, nil
362→		}
363→	}
364→	return nil, "", errors.New("transcript not found for any registered agent")
365→}
366→
367→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
368→// When force is true, it amends without prompting.
369→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
370→	// Get HEAD commit info
371→	repo, err := openRepository(ctx)
372→	if err != nil {
373→		return fmt.Errorf("failed to open repository: %w", err)
374→	}
375→	headRef, err := repo.Head()
376→	if err != nil {
377→		return fmt.Errorf("failed to get HEAD: %w", err)
378→	}
379→	headCommit, err := repo.CommitObject(headRef.Hash())
380→	if err != nil {
381→		return fmt.Errorf("failed to get HEAD commit: %w", err)
382→	}
383→
384→	shortHash := headRef.Hash().String()[:7]
385→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
386→
387→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
388→
389→	amend := true
390→	if !force {
391→		form := NewAccessibleForm(
392→			huh.NewGroup(
393→				huh.NewConfirm().
394→					Title("Amend the last commit in this branch?").
395→					Affirmative("Y").
396→					Negative("n").
397→					Value(&amend),
398→			),
399→		)
400→		if err := form.Run(); err != nil {
401→			return fmt.Errorf("prompt failed: %w", err)
402→		}
403→	}
404→
405→	if !amend {
406→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
407→		return nil
408→	}
409→
410→	// Skip amending if this exact checkpoint ID is already in the commit
411→	for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
412→		if existing.String() == checkpointIDStr {
413→			fmt.Fprintf(w, "Commit already has Entire-Checkpoint: %s (skipping amend)\n", checkpointIDStr)
414→			return nil
415→		}
416→	}
417→
418→	// Amend the commit with the checkpoint trailer.
419→	// If the message already has trailers, append on a new line; otherwise add a blank line first.
420→	trimmed := strings.TrimRight(headCommit.Message, "\n")
421→	trailer := fmt.Sprintf("%s: %s", trailers.CheckpointTrailerKey, checkpointIDStr)
422→	var newMessage string
423→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
424→		newMessage = fmt.Sprintf("%s\n%s\n", trimmed, trailer)
425→	} else {
426→		newMessage = fmt.Sprintf("%s\n\n%s\n", trimmed, trailer)
427→	}
428→
429→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
430→	if output, err := cmd.CombinedOutput(); err != nil {
431→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
432→	}
433→
434→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
435→	return nil
436→}
437→
438→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
439→// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
440→func extractFirstPromptFromTranscript(data []byte) string {
441→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
442→	lines, err := transcript.ParseFromBytes(data)
443→	if err == nil {
444→		for _, line := range lines {
445→			if line.Type == transcript.TypeUser {
446→				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
447→					return prompt
448→				}
449→			}
450→		}
451→	}
452→
453→	// Fallback: try Gemini JSON format {"messages": [...]}
454→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
455→		return prompts[0]
456→	}
457→
458→	return ""
459→}
460→
461→// normalizeGeminiTranscript normalizes user message content fields in-place from
462→// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
463→// (timestamps, thoughts, tokens, model, toolCalls, etc.).
464→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
465→	var raw map[string]json.RawMessage
466→	if err := json.Unmarshal(data, &raw); err != nil {
467→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
468→	}
469→
470→	messagesRaw, ok := raw["messages"]
471→	if !ok {
472→		return data, nil
473→	}
474→
475→	var messages []json.RawMessage
476→	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
477→		return nil, fmt.Errorf("failed to parse messages: %w", err)
478→	}
479→
480→	changed := false
481→	for i, msgRaw := range messages {
482→		var msg map[string]json.RawMessage
483→		if err := json.Unmarshal(msgRaw, &msg); err != nil {
484→			continue
485→		}
486→
487→		contentRaw, hasContent := msg["content"]
488→		if !hasContent || len(contentRaw) == 0 {
489→			continue
490→		}
491→
492→		// Skip if already a string
493→		var strContent string
494→		if json.Unmarshal(contentRaw, &strContent) == nil {
495→			continue
496→		}
497→
498→		// Try to convert array of {"text":"..."} to a plain string
499→		var parts []struct {
500→			Text string `json:"text"`
501→		}
502→		if json.Unmarshal(contentRaw, &parts) != nil {
503→			continue
504→		}
505→
506→		var texts []string
507→		for _, p := range parts {
508→			if p.Text != "" {
509→				texts = append(texts, p.Text)
510→			}
511→		}
512→		joined := strings.Join(texts, "\n")
513→		strBytes, err := json.Marshal(joined)
514→		if err != nil {
515→			continue
516→		}
517→		msg["content"] = strBytes
518→		rewritten, err := json.Marshal(msg)
519→		if err != nil {
520→			continue
521→		}
522→		messages[i] = rewritten
523→		changed = true
524→	}
525→
526→	if !changed {
527→		return data, nil
528→	}
529→
530→	rewrittenMessages, err := json.Marshal(messages)
531→	if err != nil {
532→		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
533→	}
534→	raw["messages"] = rewrittenMessages
535→
536→	return json.MarshalIndent(raw, "", "  ")
537→}
538→
539→// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
540→// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
541→func countUserTurns(data []byte) int {
542→	// Try JSONL format first — use ExtractUserContent to distinguish
543→	// real user prompts from tool_result messages (both have type "user").
544→	lines, err := transcript.ParseFromBytes(data)
545→	if err == nil {
546→		count := 0
547→		for _, line := range lines {
548→			if line.Type == transcript.TypeUser {
549→				if transcript.ExtractUserContent(line.Message) != "" {
550→					count++
551→				}
552→			}
553→		}
554→		if count > 0 {
555→			return count
556→		}
557→	}
558→
559→	// Fallback: Gemini JSON format
560→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
561→		return len(prompts)
562→	}
563→
564→	return 0
565→}
566→
567→// extractModelFromTranscript extracts the model name from a JSONL transcript.
568→// Best-effort: returns empty string if the transcript format doesn't include model info
569→// (e.g., Gemini stores model info in hook events, not the transcript).
570→func extractModelFromTranscript(data []byte) string {
571→	lines, err := transcript.ParseFromBytes(data)
572→	if err != nil {
573→		return ""
574→	}
575→
576→	for _, line := range lines {
577→		if line.Type != transcript.TypeAssistant {
578→			continue
579→		}
580→		var msg struct {
581→			Model string `json:"model"`
582→		}
583→		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
584→			return msg.Model
585→		}
586→	}
587→	return ""
588→}
589→
590→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
591→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
592→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
593→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
594→func estimateSessionDuration(data []byte) int64 {
595→	type timestamped struct {
596→		Timestamp string `json:"timestamp"`
597→	}
598→
599→	var first, last time.Time
600→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
601→		if len(rawLine) == 0 {
602→			continue
603→		}
604→		var ts timestamped
605→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
606→			continue
607→		}
608→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
609→		if err != nil {
610→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
611→			if err != nil {
612→				continue
613→			}
614→		}
615→		if first.IsZero() {
616→			first = parsed
617→		}
618→		last = parsed
619→	}
620→
621→	if first.IsZero() || last.IsZero() || !last.After(first) {
622→		return 0
623→	}
624→	return last.Sub(first).Milliseconds()
625→}
