 32→func newAttachCmd() *cobra.Command {
 33→	var (
 34→		force     bool
 35→		agentFlag string
 36→	)
 37→	cmd := &cobra.Command{
 38→		Use:   "attach <session-id>",
 39→		Short: "Attach an existing agent session",
 40→		Long: `Attach an existing agent session that wasn't captured by hooks.
 41→
 42→This creates a checkpoint from the session's transcript and registers the
 43→session for future tracking. Use this when hooks failed to fire or weren't
 44→installed when the session started.
 45→
 46→Supported agents: claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid`,
 47→		Args: cobra.ExactArgs(1),
 48→		RunE: func(cmd *cobra.Command, args []string) error {
 49→			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
 50→				return nil
 51→			}
 52→			agentName := types.AgentName(agentFlag)
 53→			return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
 54→		},
 55→	}
 56→	cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
 57→	cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid)")
 58→	return cmd
 59→}
