 15→// IsAccessibleMode returns true if accessibility mode should be enabled.
 16→// This checks the ACCESSIBLE environment variable.
 17→// Set ACCESSIBLE=1 (or any non-empty value) to enable accessible mode,
 18→// which uses simpler prompts that work better with screen readers.
 19→func IsAccessibleMode() bool {
 20→	return os.Getenv("ACCESSIBLE") != ""
 21→}
 22→
 23→// entireTheme returns the Dracula theme for consistent styling.
 24→func entireTheme() *huh.Theme {
 25→	return huh.ThemeDracula()
 26→}
