 28→// NewAccessibleForm creates a new huh form with accessibility mode
 29→// enabled if the ACCESSIBLE environment variable is set.
 30→// Note: WithAccessible() is only available on forms, not individual fields.
 31→// Always wrap confirmations and other prompts in a form to enable accessibility.
 32→func NewAccessibleForm(groups ...*huh.Group) *huh.Form {
 33→	form := huh.NewForm(groups...).WithTheme(entireTheme())
 34→	if IsAccessibleMode() {
 35→		form = form.WithAccessible(true)
 36→	}
 37→	return form
 38→}
