114→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
115→// as the main transcript.
116→func AgentTranscriptPath(transcriptDir, agentID string) string {
117→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
118→}
