128→// GetLogsOnlyRewindPoints finds commits in the current branch's history that have
129→// condensed session logs on the entire/checkpoints/v1 branch. These are commits that
130→// were created with session data but the shadow branch has been condensed.
131→//
132→// The function works by:
133→// 1. Getting all checkpoints from the entire/checkpoints/v1 branch
134→// 2. Building a map of checkpoint ID -> checkpoint info
135→// 3. Scanning the current branch history for commits with Entire-Checkpoint trailers
136→// 4. Matching by checkpoint ID (stable across amend/rebase)
137→func (s *ManualCommitStrategy) GetLogsOnlyRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
138→	repo, err := OpenRepository(ctx)
139→	if err != nil {
140→		return nil, err
141→	}
142→
143→	// Get all checkpoints from entire/checkpoints/v1 branch
144→	checkpoints, err := s.listCheckpoints(ctx)
145→	if err != nil {
146→		// No checkpoints yet is fine
147→		return nil, nil //nolint:nilerr // Expected when no checkpoints exist
148→	}
149→
150→	if len(checkpoints) == 0 {
151→		return nil, nil
152→	}
153→
154→	// Build map of checkpoint ID -> checkpoint info
155→	// Checkpoint ID is the stable link from Entire-Checkpoint trailer
156→	checkpointInfoMap := make(map[id.CheckpointID]CheckpointInfo)
157→	for _, cp := range checkpoints {
158→		if !cp.CheckpointID.IsEmpty() {
159→			checkpointInfoMap[cp.CheckpointID] = cp
160→		}
161→	}
162→
163→	// Get metadata branch tree for reading session prompts (best-effort, ignore errors)
164→	metadataTree, _ := GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort for session prompts
165→
166→	head, err := repo.Head()
167→	if err != nil {
168→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
169→	}
170→
171→	// Use LogOptions with Order=LogOrderCommitterTime to traverse all parents of merge commits.
172→	iter, err := repo.Log(&git.LogOptions{
173→		From:  head.Hash(),
174→		Order: git.LogOrderCommitterTime,
175→	})
176→	if err != nil {
177→		return nil, fmt.Errorf("failed to get commit log: %w", err)
178→	}
179→
180→	var points []RewindPoint
181→	count := 0
182→
183→	err = iter.ForEach(func(c *object.Commit) error {
184→		if err := ctx.Err(); err != nil {
185→			return err //nolint:wrapcheck // Propagating context cancellation
186→		}
187→		if count >= logsOnlyScanLimit {
188→			return errStop
189→		}
190→		count++
191→
192→		// Extract all checkpoint IDs from Entire-Checkpoint trailers.
193→		// Squash merge commits may contain multiple trailers from the original commits.
194→		allCpIDs := trailers.ParseAllCheckpoints(c.Message)
195→		if len(allCpIDs) == 0 {
196→			return nil
197→		}
198→
199→		// Resolve to the latest checkpoint by creation time (consistent with `entire resume`).
200→		cpInfo, found := ResolveLatestCheckpointFromMap(allCpIDs, checkpointInfoMap)
201→		if !found {
202→			return nil
203→		}
204→
205→		// Create logs-only rewind point
206→		message := strings.Split(c.Message, "\n")[0]
207→
208→		// Read session prompts from metadata tree
209→		var sessionPrompt string
210→		var sessionPrompts []string
211→		if metadataTree != nil {
212→			checkpointPath := paths.CheckpointPath(cpInfo.CheckpointID) //nolint:staticcheck // already present in codebase
213→			// For multi-session checkpoints, read all prompts
214→			if cpInfo.SessionCount > 1 && len(cpInfo.SessionIDs) > 1 {
215→				sessionPrompts = ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, cpInfo.SessionCount, cpInfo.SessionIDs)
216→				// Use the last (most recent) prompt as the main session prompt
217→				if len(sessionPrompts) > 0 {
218→					sessionPrompt = sessionPrompts[len(sessionPrompts)-1]
219→				}
220→			} else {
221→				sessionPrompt = ReadSessionPromptFromTree(metadataTree, checkpointPath)
222→				if sessionPrompt != "" {
223→					sessionPrompts = []string{sessionPrompt}
224→				}
225→			}
226→		}
227→
228→		points = append(points, RewindPoint{
229→			ID:             c.Hash.String(),
230→			Message:        message,
231→			Date:           c.Author.When,
232→			IsLogsOnly:     true,
233→			CheckpointID:   cpInfo.CheckpointID,
234→			Agent:          cpInfo.Agent,
235→			SessionID:      cpInfo.SessionID,
236→			SessionPrompt:  sessionPrompt,
237→			SessionCount:   cpInfo.SessionCount,
238→			SessionIDs:     cpInfo.SessionIDs,
239→			SessionPrompts: sessionPrompts,
240→		})
241→
242→		return nil
243→	})
244→
245→	if err != nil && !errors.Is(err, errStop) {
246→		return nil, fmt.Errorf("error iterating commits: %w", err)
247→	}
248→
249→	if len(points) > limit {
250→		points = points[:limit]
251→	}
252→
253→	return points, nil
254→}
