256→// ResolveLatestCheckpointFromMap picks the checkpoint with the latest CreatedAt
257→// from a list of checkpoint IDs. Filters to IDs present in infoMap, then picks
258→// the one with the most recent CreatedAt.
259→func ResolveLatestCheckpointFromMap(cpIDs []id.CheckpointID, infoMap map[id.CheckpointID]CheckpointInfo) (CheckpointInfo, bool) {
260→	var found bool
261→	var latest CheckpointInfo
262→	for _, cpID := range cpIDs {
263→		info, ok := infoMap[cpID]
264→		if !ok {
265→			continue
266→		}
267→		if !found || info.CreatedAt.After(latest.CreatedAt) {
268→			latest = info
269→			found = true
270→		}
271→	}
272→	return latest, found
273→}
