275→// Rewind restores the working directory to a checkpoint.
276→//
277→
278→func (s *ManualCommitStrategy) Rewind(ctx context.Context, point RewindPoint) error {
279→	repo, err := OpenRepository(ctx)
280→	if err != nil {
281→		return fmt.Errorf("failed to open git repository: %w", err)
282→	}
283→
284→	// Get the checkpoint commit
285→	commitHash := plumbing.NewHash(point.ID)
286→	commit, err := repo.CommitObject(commitHash)
287→	if err != nil {
288→		return fmt.Errorf("failed to get commit: %w", err)
289→	}
290→
291→	tree, err := commit.Tree()
292→	if err != nil {
293→		return fmt.Errorf("failed to get tree: %w", err)
294→	}
295→
296→	// Reset the shadow branch to the rewound checkpoint
297→	// This ensures the next checkpoint will only include prompts from this point forward
298→	if err := s.resetShadowBranchToCheckpoint(ctx, repo, commit); err != nil {
299→		// Log warning but don't fail - file restoration is the primary operation
300→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
301→	}
302→
303→	// Load session state to get untracked files that existed at session start
304→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
305→	var preservedUntrackedFiles map[string]bool
306→	if hasSessionTrailer {
307→		state, stateErr := s.loadSessionState(ctx, sessionID)
308→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
309→			preservedUntrackedFiles = make(map[string]bool)
310→			for _, f := range state.UntrackedFilesAtStart {
311→				preservedUntrackedFiles[f] = true
312→			}
313→		}
314→	}
315→
316→	// Build set of files in the checkpoint tree (excluding metadata)
317→	checkpointFiles := make(map[string]bool)
318→	err = tree.Files().ForEach(func(f *object.File) error {
319→		if err := ctx.Err(); err != nil {
320→			return err //nolint:wrapcheck // Propagating context cancellation
321→		}
322→		if !strings.HasPrefix(f.Name, entireDir) {
323→			checkpointFiles[f.Name] = true
324→		}
325→		return nil
326→	})
327→	if err != nil {
328→		return fmt.Errorf("failed to list checkpoint files: %w", err)
329→	}
330→
331→	// Get HEAD tree to identify tracked files
332→	head, err := repo.Head()
333→	if err != nil {
334→		return fmt.Errorf("failed to get HEAD: %w", err)
335→	}
336→	headCommit, err := repo.CommitObject(head.Hash())
337→	if err != nil {
338→		return fmt.Errorf("failed to get HEAD commit: %w", err)
339→	}
340→	headTree, err := headCommit.Tree()
341→	if err != nil {
342→		return fmt.Errorf("failed to get HEAD tree: %w", err)
343→	}
344→
345→	// Build set of files tracked in HEAD
346→	trackedFiles := make(map[string]bool)
347→	//nolint:errcheck // Error is not critical for rewind
348→	_ = headTree.Files().ForEach(func(f *object.File) error {
349→		if err := ctx.Err(); err != nil {
350→			return err //nolint:wrapcheck // Propagating context cancellation
351→		}
352→		trackedFiles[f.Name] = true
353→		return nil
354→	})
355→
356→	// Get repository root to walk from there
357→	repoRoot, err := paths.WorktreeRoot(ctx)
358→	if err != nil {
359→		repoRoot = "." // Fallback to current directory
360→	}
361→
362→	// Open os.Root at repo root for traversal-resistant file operations.
363→	// Defense-in-depth: paths come from git tree objects (trusted) but we
364→	// still scope operations to prevent any escape from the repo root.
365→	repoRootHandle, err := os.OpenRoot(repoRoot)
366→	if err != nil {
367→		return fmt.Errorf("failed to open repo root: %w", err)
368→	}
369→	defer repoRootHandle.Close()
370→
371→	// Find and delete untracked files that aren't in the checkpoint.
372→	// Uses git ls-files to only consider non-ignored files, avoiding walks through
373→	// large ignored directories like node_modules/.
374→	untrackedNow, err := collectUntrackedFiles(ctx)
375→	if err != nil {
376→		// Non-fatal - continue with restoration
377→		fmt.Fprintf(os.Stderr, "Warning: error listing untracked files: %v\n", err)
378→	}
379→	for _, relPath := range untrackedNow {
380→		// If file is in checkpoint, it will be restored
381→		if checkpointFiles[relPath] {
382→			continue
383→		}
384→
385→		// If file is tracked in HEAD, don't delete (user's committed work)
386→		if trackedFiles[relPath] {
387→			continue
388→		}
389→
390→		// If file existed at session start, preserve it (untracked user files)
391→		if preservedUntrackedFiles[relPath] {
392→			continue
393→		}
394→
395→		// File is untracked and not in checkpoint - delete it via os.Root
396→		if removeErr := osroot.Remove(repoRootHandle, relPath); removeErr == nil {
397→			fmt.Fprintf(os.Stderr, "  Deleted: %s\n", relPath)
398→		}
399→	}
400→
401→	// Restore files from checkpoint
402→	err = tree.Files().ForEach(func(f *object.File) error {
403→		if err := ctx.Err(); err != nil {
404→			return err //nolint:wrapcheck // Propagating context cancellation
405→		}
406→		// Skip metadata directories - these are for checkpoint storage, not working dir
407→		if strings.HasPrefix(f.Name, entireDir) {
408→			return nil
409→		}
410→
411→		contents, err := f.Contents()
412→		if err != nil {
413→			return fmt.Errorf("failed to read file %s: %w", f.Name, err)
414→		}
415→
416→		// Ensure directory exists (MkdirAll not available on os.Root)
417→		absPath := filepath.Join(repoRoot, f.Name)
418→		dir := filepath.Dir(absPath)
419→		if dir != "." {
420→			//nolint:gosec // G301: Need 0o755 for user directories during rewind
421→			if err := os.MkdirAll(dir, 0o755); err != nil {
422→				return fmt.Errorf("failed to create directory %s: %w", dir, err)
423→			}
424→		}
425→
426→		// Write file with appropriate permissions via os.Root
427→		var perm os.FileMode = 0o644
428→		if f.Mode == filemode.Executable {
429→			perm = 0o755
430→		}
431→		if err := osroot.WriteFile(repoRootHandle, f.Name, []byte(contents), perm); err != nil {
432→			return fmt.Errorf("failed to write file %s: %w", f.Name, err)
433→		}
434→
435→		fmt.Fprintf(os.Stderr, "  Restored: %s\n", f.Name)
436→		return nil
437→	})
438→	if err != nil {
439→		return fmt.Errorf("failed to iterate tree files: %w", err)
440→	}
441→
442→	fmt.Println()
443→	if len(point.ID) >= 7 {
444→		fmt.Printf("Restored files from shadow commit %s\n", point.ID[:7])
445→	} else {
446→		fmt.Printf("Restored files from shadow commit %s\n", point.ID)
447→	}
448→	fmt.Println()
449→
450→	return nil
451→}
