488→// and will be replaced by the checkpoint contents. Returns true with a warning message showing
489→// what changes will be reverted.
490→func (s *ManualCommitStrategy) CanRewind(ctx context.Context) (bool, string, error) {
491→	return checkCanRewindWithWarning(ctx)
