832→+func newAttachCmd() *cobra.Command {
833→+	var (
834→+		force     bool
835→+		agentFlag string
836→+	)
837→+	cmd := &cobra.Command{
838→+		Use:   "attach <session-id>",
839→+		Short: "Attach an existing agent session",
840→+		Long: `Attach an existing agent session that wasn't captured by hooks.
841→+
842→+This creates a checkpoint from the session's transcript and registers the
843→+session for future tracking. Use this when hooks failed to fire or weren't
844→+installed when the session started.
845→+
846→+Supported agents: claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid`,
847→+		Args: cobra.ExactArgs(1),
848→+		RunE: func(cmd *cobra.Command, args []string) error {
849→+			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
850→+				return nil
851→+			}
852→+			agentName := types.AgentName(agentFlag)
853→+			return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
854→+		},
855→+	}
856→+	cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
857→+	cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid)")
858→+	return cmd
859→+}
