 861→+func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 862→+	logCtx := logging.WithComponent(ctx, "attach")
 863→+
 864→+	// Validate session ID format
 865→+	if err := validation.ValidateSessionID(sessionID); err != nil {
 866→+		return fmt.Errorf("invalid session ID: %w", err)
 867→+	}
 868→+
 869→+	// Ensure we're in a git repo
 870→+	repoRoot, err := paths.WorktreeRoot(ctx)
 871→+	if err != nil {
 872→+		return fmt.Errorf("not a git repository: %w", err)
 873→+	}
 874→+
 875→+	// Bail out early if repo has no commits (strategy requires HEAD)
 876→+	if repo, repoErr := strategy.OpenRepository(ctx); repoErr == nil && strategy.IsEmptyRepository(repo) {
 877→+		return errors.New("repository has no commits yet — make an initial commit before running attach")
 878→+	}
 879→+
 880→+	// Check session isn't already tracked
 881→+	store, err := session.NewStateStore(ctx)
 882→+	if err != nil {
 883→+		return fmt.Errorf("failed to open session store: %w", err)
 884→+	}
 885→+	existing, err := store.Load(ctx, sessionID)
 886→+	if err != nil {
 887→+		return fmt.Errorf("failed to check existing session: %w", err)
 888→+	}
 889→+	if existing != nil {
 890→+		return fmt.Errorf("session %s is already tracked by Entire", sessionID)
 891→+	}
 892→+
 893→+	// Resolve agent and transcript path (auto-detect agent if transcript not found)
 894→+	ag, err := agent.Get(agentName)
 895→+	if err != nil {
 896→+		return fmt.Errorf("agent %q not available: %w", agentName, err)
 897→+	}
 898→+
 899→+	transcriptPath, err := resolveAndValidateTranscript(logCtx, sessionID, agentName, ag)
 900→+	if err != nil {
 901→+		// Try other agents to auto-detect
 902→+		if detectedAg, detectedPath, detectErr := detectAgentByTranscript(logCtx, sessionID, agentName); detectErr == nil {
 903→+			ag = detectedAg
 904→+			transcriptPath = detectedPath
 905→+			logging.Info(logCtx, "auto-detected agent from transcript", "agent", ag.Name())
 906→+			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
 907→+		} else {
 908→+			return err // return original error
 909→+		}
 910→+	}
 911→+	agentType := ag.Type()
 912→+
 913→+	// Read transcript data
 914→+	transcriptData, err := ag.ReadTranscript(transcriptPath)
 915→+	if err != nil {
 916→+		return fmt.Errorf("failed to read transcript: %w", err)
 917→+	}
 918→+
 919→+	// Extract modified files from transcript
 920→+	var modifiedFiles []string
 921→+	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
 922→+		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
 923→+			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
 924→+		} else {
 925→+			modifiedFiles = files
 926→+		}
 927→+	}
 928→+
 929→+	// Detect file changes via git status (no pre-untracked filter since we don't know pre-state)
 930→+	changes, err := DetectFileChanges(ctx, nil)
 931→+	if err != nil {
 932→+		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
 933→+	}
 934→+
 935→+	// Filter and normalize paths
 936→+	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
 937→+	var relNewFiles, relDeletedFiles []string
 938→+	if changes != nil {
 939→+		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
 940→+		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
 941→+		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
 942→+	}
 943→+
 944→+	// Filter to uncommitted files only
 945→+	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
 946→+
 947→+	if err := strategy.EnsureSetup(ctx); err != nil {
 948→+		return fmt.Errorf("failed to set up strategy: %w", err)
 949→+	}
 950→+
 951→+	// Create session metadata directory and copy transcript
 952→+	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
 953→+	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
 954→+	if err != nil {
 955→+		return fmt.Errorf("failed to resolve session directory path: %w", err)
 956→+	}
 957→+	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
 958→+		return fmt.Errorf("failed to create session directory: %w", err)
 959→+	}
 960→+	// Normalize Gemini transcripts so the content field is a plain string
 961→+	// (Gemini user messages use [{"text":"..."}] arrays, which the UI can't render).
 962→+	storedTranscript := transcriptData
 963→+	if agentType == agent.AgentTypeGemini {
 964→+		if normalized, normErr := normalizeGeminiTranscript(transcriptData); normErr == nil {
 965→+			storedTranscript = normalized
 966→+		} else {
 967→+			logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
 968→+		}
 969→+	}
 970→+	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
 971→+	if err := os.WriteFile(logFile, storedTranscript, 0o600); err != nil {
 972→+		return fmt.Errorf("failed to write transcript: %w", err)
 973→+	}
 974→+
 975→+	// Get git author
 976→+	author, err := GetGitAuthor(ctx)
 977→+	if err != nil {
 978→+		return fmt.Errorf("failed to get git author: %w", err)
 979→+	}
 980→+
 981→+	// Extract first prompt from transcript for the commit message
 982→+	firstPrompt := extractFirstPromptFromTranscript(transcriptData)
 983→+	commitMessage := generateCommitMessage(firstPrompt, agentType)
 984→+
 985→+	// Write prompt.txt so SaveStep includes it on the shadow branch
 986→+	// and CondenseSession can read it for the checkpoint metadata.
 987→+	if firstPrompt != "" {
 988→+		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
 989→+		if err := os.WriteFile(promptFile, []byte(firstPrompt), 0o600); err != nil {
 990→+			logging.Warn(logCtx, "failed to write prompt file", "error", err)
 991→+		}
 992→+	}
 993→+
 994→+	// Initialize session state BEFORE SaveStep so it exists when SaveStep loads it.
 995→+	// Use logFile (the normalized local copy) as the transcript path so that
 996→+	// CondenseSession reads the normalized version instead of the raw agent file.
 997→+	strat := GetStrategy(ctx)
 998→+	if err := strat.InitializeSession(ctx, sessionID, agentType, logFile, firstPrompt, ""); err != nil {
 999→+		return fmt.Errorf("failed to initialize session: %w", err)
1000→+	}
1001→+
1002→+	// Enrich session state with transcript-derived metadata
1003→+	if err := enrichSessionState(logCtx, sessionID, ag, transcriptData, logFile); err != nil {
1004→+		return err
1005→+	}
1006→+
1007→+	// Build step context and save checkpoint.
1008→+	// Use the local (potentially normalized) transcript so SaveStep stores the cleaned version.
1009→+	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
1010→+
1011→+	stepCtx := strategy.StepContext{
1012→+		SessionID:      sessionID,
1013→+		ModifiedFiles:  relModifiedFiles,
1014→+		NewFiles:       relNewFiles,
1015→+		DeletedFiles:   relDeletedFiles,
1016→+		MetadataDir:    sessionDir,
1017→+		MetadataDirAbs: sessionDirAbs,
1018→+		CommitMessage:  commitMessage,
1019→+		TranscriptPath: logFile,
1020→+		AuthorName:     author.Name,
1021→+		AuthorEmail:    author.Email,
1022→+		AgentType:      agentType,
1023→+	}
1024→+
1025→+	if err := strat.SaveStep(ctx, stepCtx); err != nil {
1026→+		return fmt.Errorf("failed to save checkpoint: %w", err)
1027→+	}
1028→+
1029→+	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
1030→+
1031→+	// Print confirmation
1032→+	fmt.Fprintf(w, "Attached session %s\n", sessionID)
1033→+	if totalChanges > 0 {
1034→+		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
1035→+	} else {
1036→+		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
1037→+	}
1038→+	if condenseErr != nil {
1039→+		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
1040→+	}
1041→+	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
1042→+
1043→+	// Offer to amend the last commit with the checkpoint trailer
1044→+	if checkpointIDStr != "" {
1045→+		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
1046→+			logging.Warn(logCtx, "failed to amend commit", "error", err)
1047→+			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
1048→+		}
1049→+	}
1050→+
1051→+	return nil
1052→+}
1053→+
1054→+// enrichSessionState loads the session state after initialization and populates it with
1055→+// transcript-derived metadata (token usage, turn count, model name, duration).
1056→+func enrichSessionState(ctx context.Context, sessionID string, ag agent.Agent, transcriptData []byte, transcriptPath string) error {
1057→+	state, err := strategy.LoadSessionState(ctx, sessionID)
1058→+	if err != nil {
1059→+		return fmt.Errorf("failed to load session state: %w", err)
1060→+	}
1061→+	if state == nil {
1062→+		return fmt.Errorf("session state not found after initialization (session_id=%s)", sessionID)
1063→+	}
1064→+	state.CLIVersion = versioninfo.Version
1065→+	state.TranscriptPath = transcriptPath
1066→+
1067→+	if usage := agent.CalculateTokenUsage(ctx, ag, transcriptData, 0, ""); usage != nil {
1068→+		state.TokenUsage = usage
1069→+	}
1070→+	if turns := countUserTurns(transcriptData); turns > 0 {
1071→+		state.SessionTurnCount = turns
1072→+	}
1073→+	if model := extractModelFromTranscript(transcriptData); model != "" {
1074→+		state.ModelName = model
1075→+	}
1076→+	if dur := estimateSessionDuration(transcriptData); dur > 0 {
1077→+		state.SessionDurationMs = dur
1078→+	}
1079→+
1080→+	if err := strategy.SaveSessionState(ctx, state); err != nil {
1081→+		return fmt.Errorf("failed to save session state: %w", err)
1082→+	}
1083→+	return nil
1084→+}
1085→+
1086→+// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
1087→+// Returns the checkpoint ID string and any condensation error.
1088→+func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
1089→+	var checkpointIDStr string
1090→+	var condenseErr error
1091→+	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
1092→+		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
1093→+		condenseErr = err
1094→+	}
1095→+
1096→+	// Single load serves both checkpoint ID extraction and finalization
1097→+	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
1098→+	if loadErr != nil {
1099→+		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
1100→+		return checkpointIDStr, condenseErr
1101→+	}
1102→+	if state == nil {
1103→+		return checkpointIDStr, condenseErr
1104→+	}
1105→+
1106→+	if condenseErr == nil {
1107→+		checkpointIDStr = state.LastCheckpointID.String()
1108→+	}
1109→+
1110→+	now := time.Now()
1111→+	state.LastInteractionTime = &now
1112→+	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
1113→+		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
1114→+	}
1115→+	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
1116→+		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
1117→+	}
1118→+
1119→+	return checkpointIDStr, condenseErr
1120→+}
