1122→+// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
1123→+// project directories if needed.
1124→+func resolveAndValidateTranscript(ctx context.Context, sessionID string, agentName types.AgentName, ag agent.Agent) (string, error) {
1125→+	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
1126→+	if err != nil {
1127→+		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
1128→+	}
1129→+	// If agent implements TranscriptPreparer, materialize the transcript before checking disk.
1130→+	if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
1131→+		if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
1132→+			logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
1133→+		}
1134→+	}
1135→+	// Agents use cwd-derived project directories, so the transcript may be stored under
1136→+	// a different project directory if the session was started from a different working directory.
1137→+	if _, statErr := os.Stat(transcriptPath); statErr == nil {
1138→+		return transcriptPath, nil
1139→+	}
1140→+	found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag)
1141→+	if searchErr == nil {
1142→+		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
1143→+		return found, nil
1144→+	}
1145→+	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
1146→+	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
1147→+}
