1167→+// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
1168→+// When force is true, it amends without prompting.
1169→+func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
1170→+	// Get HEAD commit info
1171→+	repo, err := openRepository(ctx)
1172→+	if err != nil {
1173→+		return fmt.Errorf("failed to open repository: %w", err)
1174→+	}
1175→+	headRef, err := repo.Head()
1176→+	if err != nil {
1177→+		return fmt.Errorf("failed to get HEAD: %w", err)
1178→+	}
1179→+	headCommit, err := repo.CommitObject(headRef.Hash())
1180→+	if err != nil {
1181→+		return fmt.Errorf("failed to get HEAD commit: %w", err)
1182→+	}
1183→+
1184→+	shortHash := headRef.Hash().String()[:7]
1185→+	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
1186→+
1187→+	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
1188→+
1189→+	amend := true
1190→+	if !force {
1191→+		form := NewAccessibleForm(
1192→+			huh.NewGroup(
1193→+				huh.NewConfirm().
1194→+					Title("Amend the last commit in this branch?").
1195→+					Affirmative("Y").
1196→+					Negative("n").
1197→+					Value(&amend),
1198→+			),
1199→+		)
1200→+		if err := form.Run(); err != nil {
1201→+			return fmt.Errorf("prompt failed: %w", err)
1202→+		}
1203→+	}
1204→+
1205→+	if !amend {
1206→+		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
1207→+		return nil
1208→+	}
1209→+
1210→+	// Skip amending if this exact checkpoint ID is already in the commit
1211→+	for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
1212→+		if existing.String() == checkpointIDStr {
1213→+			fmt.Fprintf(w, "Commit already has Entire-Checkpoint: %s (skipping amend)\n", checkpointIDStr)
1214→+			return nil
1215→+		}
1216→+	}
1217→+
1218→+	// Amend the commit with the checkpoint trailer.
1219→+	// If the message already has trailers, append on a new line; otherwise add a blank line first.
1220→+	trimmed := strings.TrimRight(headCommit.Message, "\n")
1221→+	trailer := fmt.Sprintf("%s: %s", trailers.CheckpointTrailerKey, checkpointIDStr)
1222→+	var newMessage string
1223→+	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
1224→+		newMessage = fmt.Sprintf("%s\n%s\n", trimmed, trailer)
1225→+	} else {
1226→+		newMessage = fmt.Sprintf("%s\n\n%s\n", trimmed, trailer)
1227→+	}
1228→+
1229→+	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
1230→+	if output, err := cmd.CombinedOutput(); err != nil {
1231→+		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
1232→+	}
1233→+
1234→+	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
1235→+	return nil
1236→+}
