1238→+// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
1239→+// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
1240→+func extractFirstPromptFromTranscript(data []byte) string {
1241→+	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
1242→+	lines, err := transcript.ParseFromBytes(data)
1243→+	if err == nil {
1244→+		for _, line := range lines {
1245→+			if line.Type == transcript.TypeUser {
1246→+				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
1247→+					return prompt
1248→+				}
1249→+			}
1250→+		}
1251→+	}
1252→+
1253→+	// Fallback: try Gemini JSON format {"messages": [...]}
1254→+	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
1255→+		return prompts[0]
1256→+	}
1257→+
1258→+	return ""
1259→+}
