120→// toolResultBlock represents a tool_result in a user message
121→type toolResultBlock struct {
122→	Type      string `json:"type"`
123→	ToolUseID string `json:"tool_use_id"`
124→}
125→
126→// userMessageWithToolResults represents a user message that may contain tool results
127→type userMessageWithToolResults struct {
128→	Content []toolResultBlock `json:"content"`
129→}
130→
131→// FindCheckpointUUID finds the UUID of the message containing the tool_result
132→// for the given tool_use_id. This is used to find the checkpoint point for
133→// transcript truncation when rewinding to a task.
134→// Returns the UUID and true if found, empty string and false otherwise.
135→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
136→	for _, line := range transcript {
137→		if line.Type != transcriptTypeUser {
138→			continue
139→		}
140→
141→		var msg userMessageWithToolResults
142→		if err := json.Unmarshal(line.Message, &msg); err != nil {
143→			continue
144→		}
145→
146→		for _, block := range msg.Content {
147→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
148→				return line.UUID, true
149→			}
150→		}
151→	}
152→	return "", false
153→}
154→
155→// TruncateTranscriptAtUUID returns transcript lines up to and including the
156→// line with the given UUID. If the UUID is not found or is empty, returns
157→// the entire transcript.
158→//
159→//nolint:revive // Exported for testing purposes
160→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
161→	if uuid == "" {
162→		return transcript
163→	}
164→
165→	for i, line := range transcript {
166→		if line.UUID == uuid {
167→			return transcript[:i+1]
168→		}
169→	}
170→
171→	// UUID not found, return full transcript
172→	return transcript
173→}
