200→// CleanupPrePromptState removes the state file after use
201→func CleanupPrePromptState(ctx context.Context, sessionID string) error {
202→	if err := validation.ValidateSessionID(sessionID); err != nil {
203→		return fmt.Errorf("invalid session ID for pre-prompt state cleanup: %w", err)
204→	}
205→
206→	tmpDirAbs := resolveTmpDir(ctx)
207→
208→	root, err := os.OpenRoot(tmpDirAbs)
209→	if err != nil {
