397→// getUntrackedFilesForState returns a list of untracked files using go-git
398→// Excludes .entire directory
399→func getUntrackedFilesForState(ctx context.Context) ([]string, error) {
400→	repo, err := openRepository(ctx)
401→	if err != nil {
402→		return nil, err
403→	}
404→
405→	worktree, err := repo.Worktree()
406→	if err != nil {
407→		return nil, err //nolint:wrapcheck // already present in codebase
408→	}
409→
410→	status, err := worktree.Status()
411→	if err != nil {
412→		return nil, err //nolint:wrapcheck // already present in codebase
413→	}
414→
415→	untrackedFiles := []string{}
416→	for file, st := range status {
417→		if st.Worktree == git.Untracked {
418→			// Exclude .entire directory
419→			if !paths.IsInfrastructurePath(file) {
420→				untrackedFiles = append(untrackedFiles, file)
