447→// CapturePreTaskState captures current untracked files before a Task execution
448→// and saves them to a state file.
449→// Works correctly from any subdirectory within the repository.
450→func CapturePreTaskState(ctx context.Context, toolUseID string) error {
451→	if toolUseID == "" {
452→		return errors.New("tool_use_id is required")
453→	}
454→
455→	if err := validation.ValidateToolUseID(toolUseID); err != nil {
456→		return fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
457→	}
458→
459→	// Get absolute path for tmp directory
460→	tmpDirAbs := resolveTmpDir(ctx)
461→
462→	// Create tmp directory if it doesn't exist
463→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
464→		return fmt.Errorf("failed to create tmp directory: %w", err)
465→	}
466→
467→	// Get list of untracked files (excluding .entire directory itself)
468→	untrackedFiles, err := getUntrackedFilesForState(ctx)
469→	if err != nil {
470→		return fmt.Errorf("failed to get untracked files: %w", err)
471→	}
472→
473→	// Create state file using os.Root for traversal-resistant write
474→	state := PreTaskState{
475→		ToolUseID:      toolUseID,
476→		Timestamp:      time.Now().UTC().Format(time.RFC3339),
477→		UntrackedFiles: untrackedFiles,
478→	}
479→
480→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
481→	if err != nil {
482→		return fmt.Errorf("failed to marshal state: %w", err)
483→	}
484→
485→	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
486→	root, err := os.OpenRoot(tmpDirAbs)
487→	if err != nil {
488→		return fmt.Errorf("failed to open tmp directory root: %w", err)
489→	}
490→	defer root.Close()
491→
492→	if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
493→		return fmt.Errorf("failed to write state file: %w", err)
494→	}
495→
496→	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before task",
497→		slog.Int("untracked_files", len(untrackedFiles)))
498→	return nil
499→}
