1149→+// detectAgentByTranscript tries all registered agents (except skip) to find one whose
1150→+// transcript resolution succeeds for the given session ID.
1151→+func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
1152→+	for _, name := range agent.List() {
1153→+		if name == skip {
1154→+			continue
1155→+		}
1156→+		ag, err := agent.Get(name)
1157→+		if err != nil {
