1238→+// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
1239→+// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
1240→+func extractFirstPromptFromTranscript(data []byte) string {
1241→+	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
1242→+	lines, err := transcript.ParseFromBytes(data)
1243→+	if err == nil {
1244→+		for _, line := range lines {
1245→+			if line.Type == transcript.TypeUser {
1246→+				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
1247→+					return prompt
1248→+				}
1249→+			}
1250→+		}
1251→+	}
1252→+
1253→+	// Fallback: try Gemini JSON format {"messages": [...]}
1254→+	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
1255→+		return prompts[0]
1256→+	}
1257→+
1258→+	return ""
1259→+}
1260→+
1261→+// normalizeGeminiTranscript normalizes user message content fields in-place from
1262→+// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
1263→+// (timestamps, thoughts, tokens, model, toolCalls, etc.).
1264→+func normalizeGeminiTranscript(data []byte) ([]byte, error) {
1265→+	var raw map[string]json.RawMessage
1266→+	if err := json.Unmarshal(data, &raw); err != nil {
1267→+		return nil, fmt.Errorf("failed to parse transcript: %w", err)
1268→+	}
1269→+
1270→+	messagesRaw, ok := raw["messages"]
1271→+	if !ok {
1272→+		return data, nil
1273→+	}
1274→+
1275→+	var messages []json.RawMessage
1276→+	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
1277→+		return nil, fmt.Errorf("failed to parse messages: %w", err)
1278→+	}
1279→+
1280→+	changed := false
1281→+	for i, msgRaw := range messages {
1282→+		var msg map[string]json.RawMessage
1283→+		if err := json.Unmarshal(msgRaw, &msg); err != nil {
1284→+			continue
1285→+		}
1286→+
1287→+		contentRaw, hasContent := msg["content"]
1288→+		if !hasContent || len(contentRaw) == 0 {
1289→+			continue
1290→+		}
1291→+
1292→+		// Skip if already a string
1293→+		var strContent string
1294→+		if json.Unmarshal(contentRaw, &strContent) == nil {
1295→+			continue
1296→+		}
1297→+
1298→+		// Try to convert array of {"text":"..."} to a plain string
1299→+		var parts []struct {
1300→+			Text string `json:"text"`
1301→+		}
1302→+		if json.Unmarshal(contentRaw, &parts) != nil {
1303→+			continue
1304→+		}
1305→+
1306→+		var texts []string
1307→+		for _, p := range parts {
1308→+			if p.Text != "" {
1309→+				texts = append(texts, p.Text)
1310→+			}
1311→+		}
1312→+		joined := strings.Join(texts, "\n")
1313→+		strBytes, err := json.Marshal(joined)
1314→+		if err != nil {
1315→+			continue
1316→+		}
1317→+		msg["content"] = strBytes
1318→+		rewritten, err := json.Marshal(msg)
1319→+		if err != nil {
1320→+			continue
1321→+		}
1322→+		messages[i] = rewritten
1323→+		changed = true
1324→+	}
1325→+
1326→+	if !changed {
1327→+		return data, nil
1328→+	}
1329→+
1330→+	rewrittenMessages, err := json.Marshal(messages)
1331→+	if err != nil {
1332→+		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
1333→+	}
1334→+	raw["messages"] = rewrittenMessages
1335→+
1336→+	return json.MarshalIndent(raw, "", "  ")
1337→+}
