1339→+// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
1340→+// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
1341→+func countUserTurns(data []byte) int {
1342→+	// Try JSONL format first — use ExtractUserContent to distinguish
1343→+	// real user prompts from tool_result messages (both have type "user").
1344→+	lines, err := transcript.ParseFromBytes(data)
1345→+	if err == nil {
1346→+		count := 0
1347→+		for _, line := range lines {
1348→+			if line.Type == transcript.TypeUser {
1349→+				if transcript.ExtractUserContent(line.Message) != "" {
1350→+					count++
1351→+				}
1352→+			}
1353→+		}
1354→+		if count > 0 {
1355→+			return count
1356→+		}
1357→+	}
1358→+
1359→+	// Fallback: Gemini JSON format
1360→+	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
1361→+		return len(prompts)
1362→+	}
1363→+
1364→+	return 0
1365→+}
