1367→+// extractModelFromTranscript extracts the model name from a JSONL transcript.
1368→+// Best-effort: returns empty string if the transcript format doesn't include model info
1369→+// (e.g., Gemini stores model info in hook events, not the transcript).
1370→+func extractModelFromTranscript(data []byte) string {
1371→+	lines, err := transcript.ParseFromBytes(data)
1372→+	if err != nil {
1373→+		return ""
1374→+	}
1375→+
1376→+	for _, line := range lines {
1377→+		if line.Type != transcript.TypeAssistant {
1378→+			continue
1379→+		}
1380→+		var msg struct {
1381→+			Model string `json:"model"`
1382→+		}
1383→+		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
1384→+			return msg.Model
1385→+		}
1386→+	}
1387→+	return ""
1388→+}
