1390→+// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
1391→+// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
1392→+// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
1393→+// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
1394→+func estimateSessionDuration(data []byte) int64 {
1395→+	type timestamped struct {
1396→+		Timestamp string `json:"timestamp"`
1397→+	}
1398→+
1399→+	var first, last time.Time
1400→+	for _, rawLine := range bytes.Split(data, []byte("\n")) {
1401→+		if len(rawLine) == 0 {
1402→+			continue
1403→+		}
1404→+		var ts timestamped
1405→+		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
1406→+			continue
1407→+		}
1408→+		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
1409→+		if err != nil {
1410→+			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
1411→+			if err != nil {
1412→+				continue
1413→+			}
1414→+		}
1415→+		if first.IsZero() {
1416→+			first = parsed
1417→+		}
1418→+		last = parsed
1419→+	}
1420→+
1421→+	if first.IsZero() || last.IsZero() || !last.After(first) {
1422→+		return 0
1423→+	}
1424→+	return last.Sub(first).Milliseconds()
1425→+}
