1775→+func TestNormalizeGeminiTranscript(t *testing.T) {
1776→+	t.Parallel()
1777→+
1778→+	// Raw Gemini format has content as array of objects for user messages,
1779→+	// plus extra fields (timestamp, model, tokens) that must be preserved.
1780→+	raw := []byte(`{"sessionId":"abc","messages":[{"id":"m1","type":"user","timestamp":"2026-01-01T10:00:00Z","content":[{"text":"fix the bug"}]},{"id":"m2","type":"gemini","content":"ok","model":"gemini-3-flash","tokens":{"input":100}}]}`)
