1782→+	if err != nil {
1783→+		t.Fatalf("normalizeGeminiTranscript() error: %v", err)
1784→+	}
1785→+
1786→+	// After normalization, content should be a plain string
1787→+	var result struct {
1788→+		SessionID string `json:"sessionId"`
1789→+		Messages  []struct {
1790→+			ID        string `json:"id"`
1791→+			Type      string `json:"type"`
1792→+			Content   string `json:"content"`
1793→+			Timestamp string `json:"timestamp"`
1794→+			Model     string `json:"model"`
1795→+		} `json:"messages"`
1796→+	}
1797→+	if err := json.Unmarshal(normalized, &result); err != nil {
1798→+		t.Fatalf("failed to parse normalized transcript: %v", err)
1799→+	}
1800→+	if result.SessionID != "abc" {
1801→+		t.Errorf("sessionId = %q, want %q", result.SessionID, "abc")
1802→+	}
1803→+	if len(result.Messages) != 2 {
1804→+		t.Fatalf("expected 2 messages, got %d", len(result.Messages))
1805→+	}
1806→+	if result.Messages[0].Content != "fix the bug" {
1807→+		t.Errorf("user content = %q, want %q", result.Messages[0].Content, "fix the bug")
1808→+	}
1809→+	if result.Messages[0].Timestamp != "2026-01-01T10:00:00Z" {
1810→+		t.Errorf("user timestamp = %q, want preserved", result.Messages[0].Timestamp)
1811→+	}
1812→+	if result.Messages[1].Content != "ok" {
1813→+		t.Errorf("gemini content = %q, want %q", result.Messages[1].Content, "ok")
1814→+	}
1815→+	if result.Messages[1].Model != "gemini-3-flash" {
1816→+		t.Errorf("model = %q, want preserved", result.Messages[1].Model)
1817→+	}
