2143→+// TestPrePush_PushesCheckpointBranchToOrigin verifies that PrePush pushes
2144→+// the entire/checkpoints/v1 branch to a bare remote after condensation.
2145→+func TestPrePush_PushesCheckpointBranchToOrigin(t *testing.T) {
2146→+	t.Parallel()
2147→+	env := NewFeatureBranchEnv(t)
2148→+
2149→+	// Set up bare remote
2150→+	bareDir := env.SetupBareRemote()
2151→+
2152→+	// Create a session, make changes, checkpoint, and commit (triggers condensation)
2153→+	session := env.NewSession()
2154→+	transcriptPath := session.CreateTranscript("Add auth module", []FileChange{
2155→+		{Path: "auth.go", Content: "package auth"},
2156→+	})
2157→+
2158→+	if err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(session.ID, "Add auth module", transcriptPath); err != nil {
2159→+		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
2160→+	}
2161→+
2162→+	env.WriteFile("auth.go", "package auth")
2163→+	env.GitAdd("auth.go")
2164→+
2165→+	if err := env.SimulateStop(session.ID, transcriptPath); err != nil {
2166→+		t.Fatalf("SimulateStop failed: %v", err)
2167→+	}
2168→+
2169→+	// Commit with hooks (triggers prepare-commit-msg + post-commit = condensation)
2170→+	env.GitCommitWithShadowHooks("Add auth module", "auth.go")
2171→+
2172→+	// Verify condensation happened locally
2173→+	if !env.BranchExists(paths.MetadataBranchName) {
2174→+		t.Fatal("entire/checkpoints/v1 should exist locally after condensation")
2175→+	}
2176→+
2177→+	// Run PrePush (simulates what happens during git push)
2178→+	env.RunPrePush("origin")
2179→+
2180→+	// Verify the branch arrived on the remote
2181→+	if !env.BranchExistsOnRemote(bareDir, paths.MetadataBranchName) {
2182→+		t.Error("entire/checkpoints/v1 should exist on bare remote after PrePush")
2183→+	}
2184→+
2185→+	// Verify checkpoint metadata is in the remote tree
2186→+	checkpointID := env.GetLatestCheckpointID()
2187→+	if checkpointID == "" {
2188→+		t.Fatal("should have a checkpoint ID after condensation")
2189→+	}
2190→+	summaryPath := CheckpointSummaryPath(checkpointID)
2191→+	if !fileExistsOnRemoteBranch(t, bareDir, summaryPath) {
