// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
func extractFirstPromptFromTranscript(data []byte) string {
	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
	lines, err := transcript.ParseFromBytes(data)
	if err == nil {
		for _, line := range lines {
			if line.Type == transcript.TypeUser {
				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
					return prompt
				}
			}
		}
	}

	// Fallback: try Gemini JSON format {"messages": [...]}
	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
		return prompts[0]
	}

	return ""
}

// normalizeGeminiTranscript normalizes user message content fields in-place from
// [{"text":"..."}] arrays to plain strings, preserving all other transcript fields
// (timestamps, thoughts, tokens, model, toolCalls, etc.).
func normalizeGeminiTranscript(data []byte) ([]byte, error) {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}

	messagesRaw, ok := raw["messages"]
	if !ok {
		return data, nil
	}

	var messages []json.RawMessage
	if err := json.Unmarshal(messagesRaw, &messages); err != nil {
		return nil, fmt.Errorf("failed to parse messages: %w", err)
	}

	changed := false
	for i, msgRaw := range messages {
		var msg map[string]json.RawMessage
		if err := json.Unmarshal(msgRaw, &msg); err != nil {
			continue
		}

		contentRaw, hasContent := msg["content"]
		if !hasContent || len(contentRaw) == 0 {
			continue
		}

		// Skip if already a string
		var strContent string
		if json.Unmarshal(contentRaw, &strContent) == nil {
			continue
		}

		// Try to convert array of {"text":"..."} to a plain string
		var parts []struct {
			Text string `json:"text"`
		}
		if json.Unmarshal(contentRaw, &parts) != nil {
			continue
		}

		var texts []string
		for _, p := range parts {
			if p.Text != "" {
				texts = append(texts, p.Text)
			}
		}
		joined := strings.Join(texts, "\n")
		strBytes, err := json.Marshal(joined)
		if err != nil {
			continue
		}
		msg["content"] = strBytes
		rewritten, err := json.Marshal(msg)
		if err != nil {
			continue
		}
		messages[i] = rewritten
		changed = true
	}

	if !changed {
		return data, nil
	}

	rewrittenMessages, err := json.Marshal(messages)
	if err != nil {
		return nil, fmt.Errorf("failed to re-serialize messages: %w", err)
	}
	raw["messages"] = rewrittenMessages

	return json.MarshalIndent(raw, "", "  ")
}

// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
func countUserTurns(data []byte) int {
	// Try JSONL format first — use ExtractUserContent to distinguish
	// real user prompts from tool_result messages (both have type "user").
	lines, err := transcript.ParseFromBytes(data)
	if err == nil {
		count := 0
		for _, line := range lines {
			if line.Type == transcript.TypeUser {
				if transcript.ExtractUserContent(line.Message) != "" {
					count++
				}
			}
		}
		if count > 0 {
			return count
		}
	}

	// Fallback: Gemini JSON format
	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
		return len(prompts)
	}

	return 0
}

