	if turns := countUserTurns(transcriptData); turns > 0 {
		state.SessionTurnCount = turns
	}
	if model := extractModelFromTranscript(transcriptData); model != "" {
		state.ModelName = model
	}
	if dur := estimateSessionDuration(transcriptData); dur > 0 {
		state.SessionDurationMs = dur
	}

	if err := strategy.SaveSessionState(ctx, state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}
	return nil
}

