	t.Setenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR", t.TempDir())
	// Redirect HOME so the fallback search doesn't walk real ~/.claude/projects
	t.Setenv("HOME", t.TempDir())

	var out bytes.Buffer
